import { DesignProfiles } from '../services/profiles/DesignProfiles';
import { currentLibraryRoot } from '../services/ProjectLibrary';
import { getConfigManager } from '../services/ConfigManager';
import { errorResult, okResult } from '../cli/envelope';
import { DatabaseSchemaMismatchError } from '../storage/library/database';
import type { IntentResult } from './intentTool';

export const withDesignProfiles = async (
  name: string,
  read: (profiles: DesignProfiles, accountId: string) => Promise<unknown>,
): Promise<IntentResult> => {
  const config = getConfigManager();
  const accountId = config.getUserId();
  if (!accountId || !config.isAuthenticated())
    return {
      envelope: errorResult(
        name,
        'AUTH_REQUIRED',
        'Sign in to Rivet before using saved design context.',
      ).envelope,
    };
  const profiles = new DesignProfiles({
    root: currentLibraryRoot(),
    accountId: () => config.getUserId(),
    runnerPaths: () => ({}),
  });
  try {
    const result = await read(profiles, accountId);
    if (config.getUserId() !== accountId)
      throw new Error(
        'Rivet account changed during this operation. Retry with the intended account.',
      );
    return { envelope: okResult(name, result).envelope };
  } catch (error) {
    if (!(error instanceof DatabaseSchemaMismatchError)) throw error;
    const { foundSchemaVersion, expectedSchemaVersion } = error;
    const isStorageNewer = foundSchemaVersion > expectedSchemaVersion;
    const recovery = isStorageNewer
      ? "Reconnect this Rivet integration using a build that supports the saved profile. If this integration has already been updated, reconnect its MCP connection; if it is pinned, update it through the host's plugin lifecycle first. Reopening a project does not refresh this reader."
      : 'The saved profile needs an explicit migration by a compatible owning application before this reader can use it. This MCP read does not migrate storage.';
    return {
      envelope: errorResult(
        name,
        'OPERATION_FAILED',
        `This Rivet MCP reader supports profile schema ${expectedSchemaVersion}, but the saved profile uses schema ${foundSchemaVersion}. ${recovery}`,
        {
          reason: 'storage_schema_mismatch',
          foundSchemaVersion,
          expectedSchemaVersion,
          relation: isStorageNewer ? 'storage_newer' : 'storage_older',
        },
      ).envelope,
    };
  } finally {
    await profiles.close();
  }
};
